svg.script:
const fake = { trees: 1, running: 0, waiting: 0 };
if (globalThis.__halogenProbe) {
  __halogenProbe.activity = async () => ({ trees: fake.trees, running: fake.running, waiting: fake.waiting });
}
let clicks = 0;
document.getElementById("bar").addEventListener("click", () => {
  fake.running = 1;
  setTimeout(() => {
    clicks += 1;
    document.getElementById("count").textContent = String(clicks);
    fake.running = 0;
  }, 150);
});
